INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (64, '1372fd0a-fb71-4e55-ab51-5f182f6d5a1f', 5, 'assistant', '**Có khả năng vẫn có mưa rào và dông rải rác**, đặc biệt vào chiều tối và đêm nay.

Cụ thể:
