INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (76, '1372fd0a-fb71-4e55-ab51-5f182f6d5a1f', 23, 'assistant', 'Bạn vừa kích hoạt lệnh `/learn`! 

