INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (129, '049a69e6-49ee-47ce-84a9-1fdc6ce08223', 35, 'assistant', 'Thưa Ngài, đây là thông số nhiệt độ và tình trạng hoạt động hiện tại của cỗ máy:

