INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (317, '10ef5988-9992-49b3-a821-5a3867525afc', 75, 'assistant', 'Báo cáo Ngài, dưới đây là thông số nhiệt độ thời gian thực của hệ thống (Lenovo Legion - CPU AMD Ryzen 7 7840H & GPU rời NVIDIA RTX 4050) vừa được trích xuất trực tiếp từ các cảm biến phần cứng:

---

### 🎮 1. GPU Rời (NVIDIA GeForce RTX 4050 Laptop GPU)
