INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (1024, 'ada90037-6b14-4009-9ab4-7da46f09229a', 62, 'assistant', 'Kính thưa Ngài, tôi đã tiến hành trích xuất dữ liệu thời gian thực từ các cảm biến phần cứng của hệ thống. Dưới đây là báo cáo nhiệt độ chi tiết (*All systems operational & frosty, Sir!*):

